/* Skip link */
.skip-link {
  position: absolute;
  left: 8px;
  top: -100px;
  background: var(--ink);
  color: #fff;
  padding: 10px 14px;
  border-radius: 8px;
  z-index: 100;
  text-decoration: none;
  font-weight: 600;
}
.skip-link:focus { top: 8px; }

.container {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 var(--gutter);
}

/* Announcement bar */
.announce {
  background: var(--ink);
  color: #fff;
  font-size: 13px;
  text-align: center;
  padding: 10px var(--gutter);
  letter-spacing: 0.02em;
}
.announce a {
  color: #fff;
  text-decoration: underline;
  text-underline-offset: 3px;
  margin-left: 6px;
}

/* Header */
.site-header {
  position: sticky;
  top: 0;
  background: rgba(250, 250, 247, 0.92);
  backdrop-filter: saturate(140%) blur(10px);
  border-bottom: 1px solid var(--line);
  z-index: 50;
}
.header-row {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 24px;
  padding: 16px 0;
}
.brand {
  font-family: var(--serif);
  font-weight: 600;
  font-size: 24px;
  letter-spacing: -0.01em;
  text-decoration: none;
}
.brand span { font-style: italic; }

.primary-nav ul {
  list-style: none;
  display: flex;
  gap: 28px;
  margin: 0;
  padding: 0;
  justify-content: center;
}
.primary-nav a {
  text-decoration: none;
  font-size: 14px;
  font-weight: 500;
  color: var(--ink-2);
  padding: 6px 2px;
  border-bottom: 2px solid transparent;
}
.primary-nav a[aria-current="page"] {
  color: var(--ink);
  border-bottom-color: var(--ink);
}
.primary-nav a:hover { color: var(--ink); }

.header-tools {
  display: flex;
  align-items: center;
  gap: 6px;
}
.icon-btn {
  background: transparent;
  border: 1px solid transparent;
  border-radius: 999px;
  width: 44px;
  height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--ink);
  position: relative;
}
.icon-btn:hover { background: var(--tag); }
.icon-btn svg { width: 20px; height: 20px; }
.cart-count {
  position: absolute;
  top: 6px;
  right: 4px;
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 999px;
  min-width: 18px;
  height: 18px;
  font-size: 11px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 5px;
  line-height: 1;
}

.menu-btn { display: none; }

/* Hero */
.hero {
  padding: 48px 0 64px;
}
.hero-grid {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: clamp(24px, 4vw, 56px);
  align-items: stretch;
}
.hero-copy {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 20px;
}
.eyebrow {
  font-size: 12px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--muted);
  font-weight: 600;
}
.hero h1 {
  font-family: var(--serif);
  font-weight: 500;
  font-size: clamp(40px, 6vw, 72px);
  line-height: 1.04;
  letter-spacing: -0.02em;
  margin: 0;
}
.hero h1 em { font-style: italic; color: var(--accent); }
.hero-lede {
  font-size: 17px;
  color: var(--ink-2);
  max-width: 48ch;
  margin: 0;
}
.hero-cta {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  margin-top: 8px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 22px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 15px;
  text-decoration: none;
  border: 1px solid transparent;
  min-height: 44px;
  transition: transform 0.06s ease;
}
.btn:active { transform: translateY(1px); }
.btn-primary {
  background: var(--ink);
  color: #fff;
}
.btn-primary:hover { background: #2a2a2a; }
.btn-secondary {
  background: transparent;
  color: var(--ink);
  border-color: var(--ink);
}
.btn-secondary:hover { background: var(--ink); color: #fff; }

.hero-image {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  background: #ddd6c8;
  min-height: 420px;
  aspect-ratio: 5 / 6;
}
.hero-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.hero-tag {
  position: absolute;
  left: 18px;
  bottom: 18px;
  background: rgba(255, 255, 255, 0.95);
  border-radius: 12px;
  padding: 14px 16px;
  display: flex;
  gap: 12px;
  align-items: center;
  max-width: 78%;
  box-shadow: var(--shadow);
}
.hero-tag .swatch {
  width: 44px;
  height: 44px;
  border-radius: 10px;
  background: linear-gradient(135deg, #b9a489, #6e5236);
  flex-shrink: 0;
}
.hero-tag-text { font-size: 13px; line-height: 1.35; }
.hero-tag-text strong { display: block; font-size: 14px; }
.hero-tag-text span { color: var(--muted); }

/* Trust strip */
.trust {
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  padding: 18px 0;
  background: var(--surface);
}
.trust-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  font-size: 13px;
  color: var(--ink-2);
}
.trust-list li {
  display: flex;
  align-items: center;
  gap: 10px;
  justify-content: center;
}
.trust-list svg { width: 18px; height: 18px; color: var(--accent); }

/* Section headings */
.section { padding: 72px 0; }
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 28px;
  flex-wrap: wrap;
}
.section-head h2 {
  font-family: var(--serif);
  font-weight: 500;
  font-size: clamp(28px, 4vw, 40px);
  letter-spacing: -0.01em;
  margin: 0;
  line-height: 1.1;
}
.section-head p {
  margin: 6px 0 0;
  color: var(--muted);
  max-width: 52ch;
}
.section-head .link {
  text-decoration: none;
  font-weight: 600;
  font-size: 14px;
  color: var(--ink);
  border-bottom: 1px solid var(--ink);
  padding-bottom: 2px;
}

/* Category tabs */
.tabs {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 24px;
}
.tab {
  background: transparent;
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 8px 16px;
  font-size: 14px;
  color: var(--ink-2);
  min-height: 36px;
}
.tab[aria-pressed="true"] {
  background: var(--ink);
  color: #fff;
  border-color: var(--ink);
}
.tab:hover:not([aria-pressed="true"]) { background: var(--tag); color: var(--ink); }

/* Product grid */
.product-grid {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.product-card {
  background: var(--surface);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--line);
  transition: box-shadow 0.2s ease, transform 0.2s ease;
}
.product-card:hover { box-shadow: var(--shadow); transform: translateY(-2px); }
.product-media {
  position: relative;
  aspect-ratio: 4 / 5;
  background: #ece9e1;
  overflow: hidden;
}
.product-media img {
  width: 100%; height: 100%; object-fit: cover;
  transition: transform 0.4s ease;
}
.product-card:hover .product-media img { transform: scale(1.04); }
.badge {
  position: absolute;
  top: 12px;
  left: 12px;
  background: #fff;
  color: var(--ink);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 6px 10px;
  border-radius: 999px;
}
.badge.sale { background: var(--sale); color: #fff; }
.badge.new { background: var(--accent); color: #fff; }

.wish-btn {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 38px;
  height: 38px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.92);
  border: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--ink-2);
}
.wish-btn:hover { color: var(--sale); }
.wish-btn[aria-pressed="true"] { color: var(--sale); }
.wish-btn svg { width: 18px; height: 18px; }

.product-body {
  padding: 16px 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}
.product-cat {
  font-size: 12px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.product-title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
}
.product-title a {
  text-decoration: none;
  color: var(--ink);
}
.product-title a:hover { text-decoration: underline; text-underline-offset: 3px; }
.product-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: auto;
  padding-top: 10px;
  gap: 10px;
}
.price { font-weight: 600; font-size: 15px; }
.price .was {
  color: var(--muted);
  text-decoration: line-through;
  font-weight: 400;
  margin-left: 6px;
  font-size: 13px;
}
.rating {
  font-size: 12px;
  color: var(--ink-2);
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.rating svg { width: 14px; height: 14px; color: #c79a2b; }

/* Deals */
.deals-section { background: #f1ede4; }
.deals-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 20px;
  min-height: 540px;
}
.deal {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  color: #fff;
  display: flex;
  align-items: end;
  padding: 28px;
  background-size: cover;
  background-position: center;
  text-decoration: none;
  isolation: isolate;
}
.deal::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(0,0,0,0) 30%, rgba(0,0,0,0.6) 100%);
  z-index: -1;
}
.deal-1 { grid-row: 1 / span 2; min-height: 320px; }
.deal-content { max-width: 80%; }
.deal h3 {
  font-family: var(--serif);
  font-weight: 500;
  font-size: clamp(22px, 2.6vw, 32px);
  margin: 0 0 6px;
  line-height: 1.1;
}
.deal p { margin: 0 0 14px; font-size: 14px; opacity: 0.92; }
.deal .pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: #fff;
  color: var(--ink);
  border-radius: 999px;
  padding: 8px 14px;
  font-weight: 600;
  font-size: 13px;
}
.deal:hover .pill { background: var(--ink); color: #fff; }

/* Editorial */
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
}
.article-card {
  background: var(--surface);
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--line);
  display: flex;
  flex-direction: column;
}
.article-media {
  aspect-ratio: 16 / 10;
  overflow: hidden;
  background: #e5e1d6;
}
.article-media img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.4s ease; }
.article-card:hover .article-media img { transform: scale(1.04); }
.article-body { padding: 22px; display: flex; flex-direction: column; gap: 10px; flex: 1; }
.article-meta {
  display: flex;
  gap: 10px;
  align-items: center;
  font-size: 12px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.article-cat {
  background: var(--tag);
  color: var(--ink);
  padding: 4px 10px;
  border-radius: 999px;
  font-weight: 600;
}
.article-title {
  font-family: var(--serif);
  font-weight: 500;
  font-size: 22px;
  line-height: 1.2;
  margin: 0;
}
.article-title a { text-decoration: none; color: var(--ink); }
.article-title a:hover { text-decoration: underline; text-underline-offset: 3px; }
.article-excerpt { color: var(--ink-2); font-size: 14px; margin: 0; }
.read-more {
  margin-top: auto;
  font-size: 13px;
  font-weight: 600;
  text-decoration: none;
  color: var(--ink);
  border-bottom: 1px solid var(--ink);
  align-self: flex-start;
  padding-bottom: 2px;
}

/* Newsletter */
.newsletter {
  background: var(--accent);
  color: #fff;
  border-radius: var(--radius);
  padding: clamp(28px, 5vw, 56px);
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  align-items: center;
}
.newsletter h2 {
  font-family: var(--serif);
  font-weight: 500;
  font-size: clamp(28px, 4vw, 40px);
  margin: 0 0 8px;
  line-height: 1.1;
}
.newsletter p { margin: 0; opacity: 0.85; }
.newsletter form {
  display: flex;
  gap: 8px;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.3);
  padding: 6px;
  border-radius: 999px;
}
.newsletter input[type="email"] {
  flex: 1;
  background: transparent;
  border: none;
  color: #fff;
  padding: 12px 18px;
  font-size: 15px;
  min-width: 0;
}
.newsletter input[type="email"]::placeholder { color: rgba(255,255,255,0.7); }
.newsletter input[type="email"]:focus { outline: none; }
.newsletter form:focus-within {
  outline: 3px solid #fff;
  outline-offset: 2px;
}
.newsletter button {
  background: #fff;
  color: var(--accent);
  border: none;
  border-radius: 999px;
  padding: 12px 22px;
  font-weight: 700;
  font-size: 14px;
  min-height: 44px;
}
.newsletter button:hover { background: var(--ink); color: #fff; }
.newsletter .form-help {
  margin-top: 10px;
  font-size: 12px;
  opacity: 0.75;
}
.newsletter .status {
  margin-top: 10px;
  font-size: 14px;
  min-height: 1.4em;
}

/* Footer */
.site-footer {
  border-top: 1px solid var(--line);
  padding: 56px 0 24px;
  background: var(--surface);
  margin-top: 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(3, 1fr);
  gap: 36px;
  padding-bottom: 36px;
  border-bottom: 1px solid var(--line);
}
.footer-brand { font-family: var(--serif); font-size: 22px; font-weight: 600; }
.footer-grid p { color: var(--muted); font-size: 14px; max-width: 32ch; }
.footer-col h3 {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--muted);
  margin: 0 0 14px;
}
.footer-col ul { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 10px; }
.footer-col a { text-decoration: none; color: var(--ink-2); font-size: 14px; }
.footer-col a:hover { color: var(--ink); text-decoration: underline; text-underline-offset: 3px; }
.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  padding-top: 20px;
  font-size: 13px;
  color: var(--muted);
}
.socials { display: flex; gap: 6px; }
.socials a {
  width: 38px; height: 38px; border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center;
  border: 1px solid var(--line);
  color: var(--ink-2);
}
.socials a:hover { background: var(--ink); color: #fff; border-color: var(--ink); }
.socials svg { width: 16px; height: 16px; }

/* Visually hidden but available to screen readers */
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

/* Responsive */
@media (max-width: 980px) {
  .hero-grid { grid-template-columns: 1fr; }
  .hero-image { aspect-ratio: 4 / 3; min-height: 320px; }
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .deals-grid {
    grid-template-columns: 1fr 1fr;
    grid-template-rows: auto auto auto;
    min-height: 0;
  }
  .deal-1 { grid-column: 1 / -1; grid-row: auto; min-height: 260px; }
  .editorial-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .newsletter { grid-template-columns: 1fr; }
  .trust-list { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 720px) {
  .menu-btn { display: inline-flex; }
  .primary-nav {
    display: none;
    position: absolute;
    top: 100%;
    left: 0; right: 0;
    background: var(--surface);
    border-bottom: 1px solid var(--line);
    padding: 16px var(--gutter);
  }
  .primary-nav.is-open { display: block; }
  .primary-nav ul { flex-direction: column; gap: 4px; align-items: stretch; }
  .primary-nav a {
    padding: 12px 4px;
    border-bottom: 1px solid var(--line);
  }
  .header-row { grid-template-columns: auto 1fr auto; position: relative; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 16px; }
  .editorial-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { justify-content: flex-start; }
  .section { padding: 56px 0; }
  .newsletter form { flex-direction: column; border-radius: 18px; padding: 10px; }
  .newsletter input[type="email"] { padding: 14px; }
  .newsletter button { border-radius: 12px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
}

@media (forced-colors: active) {
  .product-card, .article-card, .tab, .icon-btn {
    border: 1px solid CanvasText;
  }
  .btn-primary, .badge.sale, .badge.new, .newsletter, .deal .pill {
    forced-color-adjust: none;
  }
}

