    { h: "Help", links: ["Contact", "Shipping", "Returns", "Size guide", "FAQ"] },
    { h: "Company", links: ["Our story", "Sustainability", "Stores", "Careers", "Press"] }
  ];
  return h("footer", { className: "site-footer" },
    h("div", { className: "container" }, [
      h("div", { key: 1, className: "footer-grid" }, [
        h("div", { key: "b" }, [
          h("div", { key: 1, className: "footer-brand" }, "Maison & Co."),
          h("p", { key: 2 }, "Considered everyday clothing and home goods, made by people we know.")
        ]),
        ...cols.map((c, i) => h("div", { key: i, className: "footer-col" }, [
          h("h3", { key: "h" }, c.h),
