function App() {
  const [wishlist, setWishlist] = useState([]);
  const [cart, setCart] = useState([]);
  const [addedId, setAddedId] = useState(null);
  const [liveMsg, setLiveMsg] = useState("");

  const onWish = (id) => {
    setWishlist(w => {
      const next = w.includes(id) ? w.filter(x => x !== id) : [...w, id];
      setLiveMsg(w.includes(id) ? "Removed from wishlist." : "Added to wishlist.");
      return next;
    });
  };

  const onAdd = (p) => {
    setCart(c => [...c, p.id]);
    setAddedId(p.id);
    setLiveMsg(`${p.name} added to bag.`);
    setTimeout(() => setAddedId(null), 1500);
  };

  return h(Fragment, null, [
    h("a", { key: "skip", href: "#main", className: "skip-link" }, "Skip to main content"),
    h(AnnouncementBar, { key: "ann" }),
    h(Header, { key: "hd", cartCount: cart.length }),
